import "../../styles/teum-base.css";
import "../../styles/components/table.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type TableProps = ComponentPropsWithRef<"table"> & {
  containerClassName?: string;
};

export function Table({ className, containerClassName, ...props }: TableProps) {
  return <div className={cn("teum-table__container", containerClassName)}><table className={cn("teum-table", className)} {...props} /></div>;
}

export function TableHeader({ className, ...props }: ComponentPropsWithRef<"thead">) {
  return <thead className={cn("teum-table__header", className)} {...props} />;
}

export function TableBody({ className, ...props }: ComponentPropsWithRef<"tbody">) {
  return <tbody className={cn("teum-table__body", className)} {...props} />;
}

export function TableFooter({ className, ...props }: ComponentPropsWithRef<"tfoot">) {
  return <tfoot className={cn("teum-table__footer", className)} {...props} />;
}

export function TableRow({ className, ...props }: ComponentPropsWithRef<"tr">) {
  return <tr className={cn("teum-table__row", className)} {...props} />;
}

export function TableHead({ className, scope = "col", ...props }: ComponentPropsWithRef<"th">) {
  return <th className={cn("teum-table__head", className)} scope={scope} {...props} />;
}

export function TableCell({ className, ...props }: ComponentPropsWithRef<"td">) {
  return <td className={cn("teum-table__cell", className)} {...props} />;
}

export function TableCaption({ className, ...props }: ComponentPropsWithRef<"caption">) {
  return <caption className={cn("teum-table__caption", className)} {...props} />;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-table__container {
  scrollbar-color: var(--teum-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.teum-table__container::-webkit-scrollbar { width: 10px; height: 10px; }

.teum-table__container::-webkit-scrollbar-track { background: transparent; }

.teum-table__container::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--teum-scrollbar-thumb);
  background-clip: padding-box;
}

.teum-table__container::-webkit-scrollbar-thumb:hover { background: var(--teum-scrollbar-thumb-hover); background-clip: padding-box; }

@media (forced-colors: active) {
.teum-table__container { scrollbar-color: auto; }
}

.teum-table__container { width: 100%; overflow: auto; border: 1px solid color-mix(in oklch, var(--teum-control-border) 78%, transparent); border-radius: var(--teum-radius-container); background: var(--teum-bg-surface); }

.teum-table { width: 100%; min-width: 560px; border-collapse: separate; border-spacing: 0; color: var(--teum-fg-default); font-size: var(--teum-type-label); font-variant-numeric: tabular-nums; }

.teum-table__caption { padding: 10px 12px; color: var(--teum-fg-subtle); text-align: left; caption-side: bottom; }

.teum-table__head { height: 35px; padding: 0 12px; border-bottom: 1px solid color-mix(in oklch, var(--teum-separator) 68%, transparent); background: color-mix(in oklch, var(--teum-bg-stage) 74%, var(--teum-bg-surface)); color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); font-weight: 560; text-align: left; white-space: nowrap; }

.teum-table__cell { height: var(--teum-row-height-table); padding: 0 12px; border-bottom: 1px solid color-mix(in oklch, var(--teum-separator) 66%, transparent); color: var(--teum-fg-muted); vertical-align: middle; }

.teum-table__row:last-child .teum-table__cell { border-bottom: 0; }

.teum-table__row[data-selected] { background: var(--teum-selected); }

.teum-table__footer .teum-table__cell { background: var(--teum-bg-stage); color: var(--teum-fg-default); font-weight: 560; }

@media (hover: hover) and (pointer: fine) {
.teum-table__body .teum-table__row:hover { background: var(--teum-hover); }
}
}
